"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

function GraphCorners({ mark = "+" }: { mark?: string }) {
  const corner =
    "pointer-events-none absolute z-10 flex size-4 items-center justify-center bg-background font-mono text-sm leading-none text-graph-frame select-none"

  return (
    <>
      <span
        aria-hidden="true"
        className={cn(corner, "top-0 left-0 -translate-x-1/2 -translate-y-1/2")}
      >
        {mark}
      </span>
      <span
        aria-hidden="true"
        className={cn(corner, "top-0 right-0 translate-x-1/2 -translate-y-1/2")}
      >
        {mark}
      </span>
      <span
        aria-hidden="true"
        className={cn(
          corner,
          "bottom-0 left-0 -translate-x-1/2 translate-y-1/2"
        )}
      >
        {mark}
      </span>
      <span
        aria-hidden="true"
        className={cn(
          corner,
          "right-0 bottom-0 translate-x-1/2 translate-y-1/2"
        )}
      >
        {mark}
      </span>
    </>
  )
}

function GraphTitle({
  className,
  children,
  ...props
}: React.ComponentProps<"figcaption">) {
  return (
    <figcaption
      className={cn(
        "absolute top-0 left-1/2 z-10 -translate-x-1/2 -translate-y-1/2 bg-background px-2.5 tracking-wide whitespace-nowrap uppercase",
        className
      )}
      {...props}
    >
      <span className="graph-title-ink text-graph-accent">[ {children} ]</span>
    </figcaption>
  )
}

function GraphBody({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div className={cn("px-5 py-7 sm:px-8 sm:py-8", className)} {...props} />
  )
}

function GraphRule({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      aria-hidden="true"
      className={cn("graph-rule w-full", className)}
      {...props}
    />
  )
}

function GraphRuleY({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      aria-hidden="true"
      className={cn("graph-rule-y self-stretch", className)}
      {...props}
    />
  )
}

function GraphTrack({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      aria-hidden="true"
      className={cn("flex w-full min-w-0 select-none", className)}
      {...props}
    />
  )
}

function GraphTick({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      className={cn("min-w-[1ch] flex-1 text-center", className)}
      {...props}
    />
  )
}

function Graph({
  title,
  corner = "+",
  className,
  children,
  ...props
}: React.ComponentProps<"figure"> & {
  title?: string
  corner?: string
}) {
  const captionId = React.useId()

  return (
    <figure
      aria-labelledby={title ? captionId : undefined}
      className={cn(
        "relative min-w-0 graph-frame font-mono text-sm text-foreground",
        className
      )}
      {...props}
    >
      {title ? <GraphTitle id={captionId}>{title}</GraphTitle> : null}
      <GraphCorners mark={corner} />
      {children}
    </figure>
  )
}

export {
  Graph,
  GraphBody,
  GraphCorners,
  GraphRule,
  GraphRuleY,
  GraphTick,
  GraphTitle,
  GraphTrack,
}

import type { Transition, Variants } from "motion/react"

export const easeOutCubic = [0.215, 0.61, 0.355, 1] as const

export const DIM_OPACITY = 0.4

export function graphTransition(
  reduce: boolean | null,
  extras?: Transition
): Transition {
  if (reduce) {
    return { duration: 0 }
  }

  return {
    duration: 0.22,
    ease: easeOutCubic,
    ...extras,
  }
}

export function fadeUp(reduce: boolean | null): Variants {
  if (reduce) {
    return {
      hidden: { opacity: 1, transform: "translateY(0px)" },
      show: { opacity: 1, transform: "translateY(0px)" },
    }
  }

  return {
    hidden: { opacity: 0, transform: "translateY(8px)" },
    show: {
      opacity: 1,
      transform: "translateY(0px)",
      transition: graphTransition(false),
    },
  }
}

export function staggerList(reduce: boolean | null, stagger = 0.04): Variants {
  return {
    hidden: {},
    show: {
      transition: reduce ? { duration: 0 } : { staggerChildren: stagger },
    },
  }
}

export function fillDelay(reduce: boolean | null, index: number, step = 0.03) {
  if (reduce) {
    return 0
  }

  return Math.min(index * step, 0.28)
}

export function clamp01(value: number) {
  return Math.min(1, Math.max(0, value))
}

export const GLYPH_SETS = {
  shade: ["·", "░", "▒", "▓", "█"],
  ascii: [".", "-", "=", "#", "@"],
  hash: [".", ":", "+", "#", "█"],
  bar: ["▁", "▂", "▃", "▅", "█"],
} as const

export type GlyphSetName = keyof typeof GLYPH_SETS
export type Glyphs = GlyphSetName | readonly string[]

export const INTENSITY_GLYPHS = GLYPH_SETS.shade

export function resolveGlyphs(glyphs?: Glyphs): readonly string[] {
  if (glyphs == null) {
    return GLYPH_SETS.shade
  }

  if (typeof glyphs === "string") {
    return GLYPH_SETS[glyphs] ?? GLYPH_SETS.shade
  }

  return glyphs.length > 0 ? glyphs : GLYPH_SETS.shade
}

export function trackMarks(
  glyphs?: Glyphs,
  fallback: { empty: string; rest: string; fill: string } = {
    empty: "-",
    rest: "░",
    fill: "█",
  }
) {
  if (glyphs == null) {
    return fallback
  }

  const set = resolveGlyphs(glyphs)
  const last = set.length - 1

  return {
    empty: set[0] ?? fallback.empty,
    rest: set[Math.min(1, last)] ?? fallback.rest,
    fill: set[last] ?? fallback.fill,
  }
}

export function intensityLevel(value: number, max: number) {
  if (value <= 0 || max <= 0) {
    return 0
  }

  return Math.max(1, Math.round(clamp01(value / max) * 4))
}

export function intensityGlyph(
  level: number,
  glyphs: readonly string[] = INTENSITY_GLYPHS
) {
  if (glyphs.length === 0) {
    return "·"
  }

  const clamped = Math.min(4, Math.max(0, Math.round(level)))
  const index = Math.round((clamped / 4) * (glyphs.length - 1))
  return glyphs[index] ?? glyphs[0] ?? "·"
}

export function intensityClass(level: number, palette: GraphPalette = "mono") {
  const index = Math.min(4, Math.max(0, Math.round(level)))

  if (index <= 0) {
    return "text-graph-frame"
  }

  if (palette === "mono") {
    if (index <= 2) {
      return "text-graph-muted"
    }

    if (index === 3) {
      return "text-foreground"
    }

    return "text-graph-accent"
  }

  if (palette === "multi") {
    if (index === 1) {
      return "text-graph-accent-2"
    }

    if (index <= 3) {
      return "text-graph-accent-3"
    }

    return "text-graph-accent"
  }

  if (index <= 2) {
    return "text-graph-accent-2"
  }

  return "text-graph-accent"
}

export type GraphPalette = "mono" | "duo" | "multi"

const SERIES_TONES = [
  "text-graph-accent",
  "text-graph-accent-2",
  "text-graph-accent-3",
] as const

export function isMonoPalette(palette?: GraphPalette) {
  return palette == null || palette === "mono"
}

export function seriesClass(palette: GraphPalette | undefined, index: number) {
  if (isMonoPalette(palette)) {
    return index === 0 ? "text-graph-accent" : "text-foreground"
  }

  const count = palette === "duo" ? 2 : 3
  return SERIES_TONES[index % count]
}

export function seriesDim(
  palette: GraphPalette | undefined,
  highlighted: boolean
) {
  if (!isMonoPalette(palette) || highlighted) {
    return undefined
  }

  return { opacity: DIM_OPACITY }
}

export function toneClass(
  palette: GraphPalette | undefined,
  role: "primary" | "secondary" | "idle" | "empty"
) {
  if (role === "empty") {
    return "text-graph-frame"
  }

  if (role === "idle") {
    return "text-graph-muted"
  }

  if (role === "primary") {
    return "text-graph-accent"
  }

  return isMonoPalette(palette) ? "text-graph-muted" : "text-graph-accent-2"
}

"use client"

import { motion, useReducedMotion } from "motion/react"

import {
  Graph,
  GraphBody,
  GraphRule,
  GraphTick,
  GraphTrack,
} from "@/registry/default/graph-frame/graph-frame"
import {
  fadeUp,
  staggerList,
  toneClass,
  trackMarks,
  type Glyphs,
  type GraphPalette,
} from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

type WaterfallKind = "start" | "in" | "out" | "end"

type WaterfallItem = {
  label: string
  value: number
  display?: string
  kind?: WaterfallKind
}

type GraphWaterfallProps = {
  title: string
  items: WaterfallItem[]
  ticks?: number
  glyphs?: Glyphs
  palette?: GraphPalette
  corner?: string
  className?: string
}

function resolveKind(
  item: WaterfallItem,
  index: number,
  length: number
): WaterfallKind {
  if (item.kind) {
    return item.kind
  }

  if (index === 0) {
    return "start"
  }

  if (index === length - 1) {
    return "end"
  }

  return item.value >= 0 ? "in" : "out"
}

function formatValue(item: WaterfallItem, kind: WaterfallKind) {
  if (item.display) {
    return item.display
  }

  const absolute = Math.abs(item.value)

  if (kind === "in") {
    return `+${absolute.toLocaleString("en-US")}`
  }

  if (kind === "out") {
    return `−${absolute.toLocaleString("en-US")}`
  }

  return item.value.toLocaleString("en-US")
}

function GraphWaterfall({
  title,
  items,
  ticks = 24,
  glyphs,
  palette,
  corner,
  className,
}: GraphWaterfallProps) {
  const reduce = useReducedMotion()
  const item = fadeUp(reduce)
  const list = staggerList(reduce, 0.05)
  const marks = trackMarks(glyphs)
  let run = 0
  const segments = items.map((entry, index) => {
    const kind = resolveKind(entry, index, items.length)
    const magnitude = Math.abs(entry.value)

    if (kind === "start") {
      const from = 0
      const to = entry.value
      run = entry.value
      return { ...entry, kind, from, to }
    }

    if (kind === "in") {
      const from = run
      const to = run + magnitude
      run = to
      return { ...entry, kind, from, to }
    }

    if (kind === "out") {
      const to = run
      const from = run - magnitude
      run = from
      return { ...entry, kind, from, to }
    }

    const total = entry.value
    run = total
    return { ...entry, kind, from: 0, to: total }
  })
  const lows = segments.map((segment) => Math.min(segment.from, segment.to))
  const highs = segments.map((segment) => Math.max(segment.from, segment.to))
  const low = Math.min(0, ...lows)
  const high = Math.max(1, ...highs)
  const span = high - low || 1

  function column(value: number) {
    return Math.round(((value - low) / span) * ticks)
  }

  return (
    <Graph title={title} className={className} corner={corner}>
      <GraphBody className="flex flex-col gap-3">
        <motion.ul
          className="flex w-full flex-col gap-2"
          initial={reduce ? false : "hidden"}
          role="list"
          variants={list}
          viewport={{ once: true, amount: 0.4 }}
          whileInView="show"
        >
          {segments.map((segment, index) => {
            const start = Math.min(column(segment.from), column(segment.to))
            const end = Math.max(
              column(segment.from),
              column(segment.to),
              start + 1
            )
            const isEnd = segment.kind === "end"
            const showRule = isEnd && index > 0

            return (
              <li className="flex flex-col gap-2" key={segment.label}>
                {showRule ? <GraphRule /> : null}
                <motion.div
                  className="grid grid-cols-[7rem_minmax(0,1fr)_5.5rem] items-center gap-x-4"
                  variants={item}
                >
                  <span className="truncate text-foreground">
                    {segment.label}
                  </span>
                  <GraphTrack>
                    {Array.from({ length: ticks }, (_, cell) => {
                      const filled = cell >= start && cell < end
                      const tone = !filled
                        ? toneClass(palette, "empty")
                        : segment.kind === "out"
                          ? toneClass(palette, "secondary")
                          : segment.kind === "start"
                            ? "text-foreground"
                            : toneClass(palette, "primary")

                      return (
                        <GraphTick className={tone} key={cell}>
                          {filled ? marks.fill : marks.empty}
                        </GraphTick>
                      )
                    })}
                  </GraphTrack>
                  <span
                    className={cn(
                      "text-right tabular-nums",
                      segment.kind === "out" && toneClass(palette, "secondary"),
                      segment.kind === "end" && toneClass(palette, "primary"),
                      (segment.kind === "start" || segment.kind === "in") &&
                        "text-foreground"
                    )}
                  >
                    {formatValue(segment, segment.kind)}
                  </span>
                </motion.div>
              </li>
            )
          })}
        </motion.ul>
        <span className="sr-only">
          {segments
            .map(
              (segment) =>
                `${segment.label} ${formatValue(segment, segment.kind)}`
            )
            .join(", ")}
        </span>
      </GraphBody>
    </Graph>
  )
}

export { GraphWaterfall }
export type { GraphWaterfallProps, WaterfallItem, WaterfallKind }
